firestore.rules 수정 — appConfig 규칙 위에 videos 블록 추가:
match /videos/{videoId} {
  // 같은 학원 소속 멤버만 읽기 가능
  allow read: if isAuthenticated()
              && isAcademyMember(resource.data.academy_id);
  // teacher, admin만 영상 등록/수정/삭제 가능
  // rejected 학원은 쓰기 차단
  allow create: if isAuthenticated()
                && isStaff()
                && isMyAcademyPendingOrActive();
  allow update, delete: if isAuthenticated()
                        && isAcademyMember(resource.data.academy_id)
                        && isStaff()
                        && isMyAcademyPendingOrActive();
}
